for (const width of [320, 390]) test(`AT-N01 幅${width} CSS pxの縦画面で一覧から線を編集し、エラー・確定・復元へ到達し横図の表代替を開く`, async ({ browser }, info) => {
  test.setTimeout(90_000);
  const context = await browser.newContext({ baseURL: info.project.use.baseURL as string, viewport: { width, height: 820 }, hasTouch: true, isMobile: true });
  try {
    const page = await context.newPage(), p = createProject(`AT-N01 幅${width}の線編集`);
    const a = createEntity(p.projectId, 'character', '表から編集する人物A'), b = createEntity(p.projectId, 'character', '表から編集する人物B');
    const flag = createEntity(p.projectId, 'variable', '線の真偽条件', { key: 'mobile_gate', valueType: 'boolean', initial: { type: 'boolean', value: true } });
    const entry = createEntity(p.projectId, 'flow_node', '縦画面の入口', { nodeType: 'entry' });
    const end = createEntity(p.projectId, 'flow_node', '縦画面の終端', { nodeType: 'terminal', terminalReason: '線を復元した' });
    const unfinished = createEntity(p.projectId, 'flow_edge', '一覧から編集する未接続の線', { fromId: entry.id, toId: { unresolved: { label: '行き先未定', reason: '作者が一覧から接続する' } }, label: '一覧から編集する線', condition: { op: 'compare', variableId: flag.id, comparator: 'eq', value: { type: 'boolean', value: true } } });
    const graph = createEntity(p.projectId, 'flow_graph', '一覧の線を含むgraph', { nodeIds: [entry.id, end.id], edgeIds: [unfinished.id], entryIds: [entry.id], exitIds: [end.id] });
    p.entities.push(a, b, flag, entry, end, unfinished, graph);
    p.entities.forEach(entity => { entity.status = 'confirmed'; });
    const relationId = newId();
    p.relations.push({ id: relationId, projectId: p.projectId, revision: '0', fromId: a.id, toId: b.id, relationType: 'trust', direction: 'forward', validity: emptyValidity(), evidenceIds: [], status: 'confirmed', visibility: 'private' });
    const bytes = await exportScenario(p);
    await attachGiven(info, 'AT-N01', bytes, { cssViewport: { width, height: 820 }, browserTouchEmulation: true, actualPhysicalDevice: 'not_run', entryId: entry.id, edgeId: unfinished.id, destinationId: end.id, relationId });
    await seed(page, bytes);
    await navigate(page, /^構成/);
    await page.getByRole('tab', { name: '分岐', exact: true }).tap();
    const line = page.locator('.branch-edge').filter({ hasText: unfinished.data.label! });
    await reachable(page, line);
    await line.tap();
    const editor = page.locator('.detail-panel');
    await expect(editor.locator('#entity-name')).toHaveValue(unfinished.name);
    await editor.getByLabel('行き先未定の下書き', { exact: true }).uncheck();
    const destination = editor.getByLabel('行き先ノード', { exact: true });
    await reachable(page, destination);
    await destination.selectOption(end.id);
    const comparator = editor.locator('[data-field="condition"]').getByLabel('比較演算', { exact: true });
    // The structured Boolean selector correctly prevents an ordered operator.
    // Exercise the same invalid AST through the ordinary advanced JSON input.
    await expect(comparator.locator('option[value="lt"]')).toBeDisabled();
    const save = editor.locator('.editor-footer').getByRole('button', { name: /保存する|保存を再試行/ });
    await reachable(page, save);
    await save.tap();
    await expect(editor.locator('.editor-save-state')).toContainText('端末内保存済み');
    const details = editor.locator('details.advanced-details').filter({ has: page.locator('summary').filter({ hasText: '詳細データ・ルビ・本文リンクを編集' }) });
    await details.locator('summary').tap();
    const raw = details.getByRole('textbox', { name: '詳細データ', exact: true });
    const validData = JSON.parse(await raw.inputValue());
    expect(validData.toId).toBe(end.id);
    expect(validData.condition).toEqual(unfinished.data.condition);
    const invalidData = { ...validData, condition: { ...validData.condition, comparator: 'lt' } };
    const beforeInvalid = await authorFingerprint(page);
    await reachable(page, raw);
    await raw.fill(JSON.stringify(invalidData, null, 2));
    const issue = editor.locator('[data-field="condition"]').getByRole('alert');
    await expect(issue).toContainText('大小の比較には整数');
    await reachable(page, issue);
    await reachable(page, save);
    await expect(save).toBeDisabled();
    await expect(raw).toHaveValue(JSON.stringify(invalidData, null, 2));
    expect(await authorFingerprint(page)).toBe(beforeInvalid);
    await raw.fill(JSON.stringify(validData, null, 2));
    await expect(issue).toHaveCount(0);
    await reachable(page, save);
    await save.tap();
    await expect(editor.locator('.editor-save-state')).toContainText('端末内保存済み');
    const afterEditDimensions = await noPageWideScroll(page);
    await editor.getByRole('button', { name: '詳細を閉じる', exact: true }).tap();
    await expect(line).toContainText(end.name);
    await navigate(page, /^年表/);
    await page.getByRole('tab', { name: '関係表・図', exact: true }).tap();
    await page.getByRole('button', { name: '関係図', exact: true }).tap();
    await expect(page.locator('.world-relation-canvas > svg')).toBeVisible();
    const tableButton = page.getByRole('button', { name: '関係表', exact: true });
    await reachable(page, tableButton);
    await tableButton.tap();
    const table = page.locator('.world-relation-table');
    await expect(table).toContainText(a.name);
    await expect(table).toContainText(b.name);
    const afterTableDimensions = await noPageWideScroll(page);
    const saved = await backup(page);
    expect(saved.project.entities.find(entity => entity.id === unfinished.id)?.data).toMatchObject({ fromId: entry.id, toId: end.id, condition: unfinished.data.condition });
    const beforeRestore = await authorFingerprint(page);
    await page.locator('input[type=file][accept*=".scenario"]').setInputFiles({ name: 'N01-invalid.scenario', mimeType: 'application/zip', buffer: Buffer.from('invalid archive bytes') });
    const restorationIssue = page.locator('.backup-panel').getByRole('alert');
    await expect(restorationIssue).toBeVisible();
    await reachable(page, restorationIssue);
    expect(await authorFingerprint(page)).toBe(beforeRestore);
    const restoredContext = await browser.newContext({ baseURL: info.project.use.baseURL as string, viewport: { width, height: 820 }, hasTouch: true, isMobile: true });
    try {
      const restored = await restoredContext.newPage();
      await seed(restored, saved.bytes);
      const cold = await backup(restored);
      expect(cold.project).toEqual(saved.project);
      await navigate(restored, /^構成/);
      await restored.getByRole('tab', { name: '分岐', exact: true }).tap();
      const recoveredLine = restored.locator('.branch-edge').filter({ hasText: unfinished.data.label! });
      await reachable(restored, recoveredLine);
      await recoveredLine.tap();
      await expect(restored.locator('.detail-panel').getByLabel('行き先ノード', { exact: true })).toHaveValue(end.id);
      const restoredSave = restored.locator('.editor-footer').getByRole('button', { name: '保存する', exact: true });
      await reachable(restored, restoredSave);
      await restoredSave.tap();
      await expect(restored.locator('.editor-save-state')).toContainText('端末内保存済み');
      const restoredDimensions = await noPageWideScroll(restored);
      await attachObservation(info, 'AT-N01-observation', { width, edgeId: unfinished.id, destinationId: end.id, afterEditDimensions, afterTableDimensions, restoredDimensions, touchTargetsReached: true, dragOrHoverNeeded: false, currentAndRestoredProjectId: saved.project.projectId, actualPhysicalDevice: 'not_run' });
    } finally { await restoredContext.close(); }
  } finally { await context.close(); }
});

test('AT-N06 同じ旧作品の移行失敗と台詞の複数対象保存の容量不足を原子拒否し、通常再試行後だけ全変更を確定する', async ({ page }, info) => {
  const fixture = new Uint8Array(await readFile('tests/fixtures/rb07-production.scenario'));
  const p = (await inspectScenario(fixture, { worker: false })).project;
  const nativeRows = versionOneRows(p);
  const line = p.entities.find(entity => entity.kind === 'dialogue_line');
  if (!line || line.kind !== 'dialogue_line') throw new Error('複数対象へ影響する既存の原台詞 fixture がありません');
  const linked = p.entities.filter(entity => (entity.kind === 'localization' || entity.kind === 'recording') && entity.data.sourceLineId === line.id);
  expect(linked.length).toBeGreaterThanOrEqual(2);
  await attachGiven(info, 'AT-N06', fixture, { projectId: p.projectId, nativeVersionBefore: 10, lineId: line.id, linkedIds: linked.map(entity => entity.id), oldSnapshotIds: p.snapshots.map(snapshot => snapshot.id), failures: ['createObjectStore(importDrafts) during native versionchange throws quota once', 'projects put during normal multi-target split throws quota once'] });
  await installVersionOne(page, p, nativeRows);
  const oldNative = await image(page);
  expect(oldNative.version).toBe(10);
  const byId = <T extends { id: string }>(rows: T[]) => rows.slice().sort((a, b) => a.id < b.id ? -1 : a.id > b.id ? 1 : 0);
  expect(nativeRows.blocks.length).toBeGreaterThan(0);
  expect(oldNative.tables.blocks.rows).toEqual(byId(nativeRows.blocks));
  expect(oldNative.tables.entities.rows).toEqual(byId(nativeRows.entities));
  await page.addInitScript(name => {
    const create = IDBDatabase.prototype.createObjectStore; let armed = true;
    IDBDatabase.prototype.createObjectStore = function (...args: Parameters<IDBDatabase['createObjectStore']>) {
      if (armed && this.name === name && args[0] === 'importDrafts') { armed = false; throw new DOMException('AT-N06 native migration quota', 'QuotaExceededError'); }
      return create.apply(this, args);
    };
  }, databaseName);
  await page.goto('./');
  await expect(page.getByRole('alert').filter({ hasText: /quota|Quota/ })).toBeVisible();
  expect(await image(page)).toEqual(oldNative);
  await expect(page.locator('.app-shell')).toHaveCount(0);
  await page.getByRole('button', { name: '読み込みを再試行', exact: true }).click();
  await page.locator('.project-card').filter({ hasText: p.name }).click();
  const migrated = await backup(page);
  expect(migrated.project).toEqual(p);
  expect((await image(page)).version).toBe(70);

  // when: a normal split affects the old line, two new lines, scene ordering,
  // translations/recording review state, history and outbox in one transaction.
  await openEntity(page, 'dialogue_line', line.name);
  const tools = page.locator('.production-tools');
  await tools.locator('summary').click();
  await tools.getByLabel('分割する文字位置', { exact: true }).fill('4');
  await tools.getByLabel('台詞変更の理由', { exact: true }).fill('AT-N06 同じ複数対象の変更を再試行');
  await tools.getByRole('button', { name: '変更の影響を確認', exact: true }).click();
  await expect(tools).toContainText('新台詞 2件');
  const beforeSave = await image(page, true);
  await page.evaluate(() => {
    const put = IDBObjectStore.prototype.put; let armed = true;
    IDBObjectStore.prototype.put = function (...args: Parameters<IDBObjectStore['put']>) {
      if (armed && this.name === 'projects') { armed = false; throw new DOMException('AT-N06 multi-target save quota', 'QuotaExceededError'); }
      return put.apply(this, args);
    };
  });
  await tools.getByRole('button', { name: '確認した変更を保存', exact: true }).click();
  await expect(tools.getByRole('alert')).toContainText('容量');
  await expect(tools).toContainText('新台詞 2件');
  await expect(tools.getByLabel('分割する文字位置', { exact: true })).toHaveValue('4');
  await expect(tools.getByLabel('台詞変更の理由', { exact: true })).toHaveValue('AT-N06 同じ複数対象の変更を再試行');
  await expect(tools.getByRole('status').filter({ hasText: '表示版を確認' })).toHaveCount(0);
  expect(await image(page, true)).toEqual(beforeSave);
  await navigate(page, /^構成/);
  await openEntity(page, 'dialogue_line', line.name);
  await tools.locator('summary').click();
  await expect(tools).toContainText('新台詞 2件');
  await tools.getByRole('button', { name: '確認した変更を保存', exact: true }).click();
  await expect(tools.getByRole('status').filter({ hasText: '表示版を確認' })).toBeVisible();
  await page.reload();
  const cold = await backup(page), oldLine = cold.project.entities.find(entity => entity.id === line.id);
  if (!oldLine || oldLine.kind !== 'dialogue_line') throw new Error('保存した原台詞がありません');
  expect(oldLine.status).toBe('rejected');
  expect(oldLine.data.replacedByLineIds).toHaveLength(2);
  const newIds = oldLine.data.replacedByLineIds!;
  const newLines = newIds.map(id => cold.project.entities.find(entity => entity.id === id));
  expect(newLines.every(entity => entity?.kind === 'dialogue_line')).toBe(true);
  const originalText = line.data.text.map(block => block.text).join('\n');
  const splitText = newLines.map(entity => entity?.kind === 'dialogue_line' ? entity.data.text.map(block => block.text).join('\n') : '').join('');
  expect(splitText).toBe(originalText);
  expect(cold.project.entities.some(entity => entity.kind === 'scene' && newIds.every(id => entity.data.dialogueLineIds?.includes(id)) && !entity.data.dialogueLineIds?.includes(line.id))).toBe(true);
  for (const original of linked) expect(cold.project.entities.find(entity => entity.id === original.id)?.data).toMatchObject({ stage: 'needs_review' });
  expect(cold.project.snapshots).toEqual(p.snapshots);
  expect(cold.project.history).toHaveLength(p.history.length + 1);
  expect(BigInt(cold.project.revision)).toBe(BigInt(p.revision) + 1n);
  await attachObservation(info, 'AT-N06-observation', { oldNativeVersion: oldNative.version, currentNativeVersion: (await image(page, true)).version, rejectedMigrationNativeUnchanged: true, rejectedMultiTargetNativeUnchanged: true, observedCanonicalTables: Object.keys(beforeSave.tables), originalLineId: line.id, newLineIds: newIds, affectedLinkedIds: linked.map(entity => entity.id), coldRevision: cold.project.revision, coldHistoryLength: cold.project.history.length, oldSnapshotIds: cold.project.snapshots.map(snapshot => snapshot.id) });
});

test('AT-N10 script と javascript URL の同じ本文を編集・試読・公開 HTML で表示し、偽画像とコード条件を拒否する', async ({ page, browser }, info) => {
  // given: scriptやjavascript URLを含む文章。
  const hostile = '<script>globalThis.__ap04ManuscriptExecuted = true</script> <a href="javascript:globalThis.__ap04UrlExecuted=true">危険な URL</a>';
  const edited = `${hostile} 編集後も文字として保持😀`;
  const p = createProject('AT-N10 安全な本文');
  const scene = createEntity(p.projectId, 'scene', '安全表示する場面', { body: textToRichText(hostile) });
  const entry = createEntity(p.projectId, 'flow_node', '本文を読む入口', { nodeType: 'entry', sceneId: scene.id });
  const end = createEntity(p.projectId, 'flow_node', '安全表示の終端', { nodeType: 'terminal', terminalReason: '表示終了' });
  const edge = createEntity(p.projectId, 'flow_edge', '安全な条件', { fromId: entry.id, toId: end.id, label: '安全な条件で進む', condition: { op: 'constant', value: true } });
  const graph = createEntity(p.projectId, 'flow_graph', '安全表示の分岐', { nodeIds: [entry.id, end.id], edgeIds: [edge.id], entryIds: [entry.id], exitIds: [end.id] });
  p.entities.push(scene, entry, end, edge, graph);
  p.entities.forEach(entity => { entity.status = 'confirmed'; });
  const bytes = await exportScenario(p);
  await attachGiven(info, 'AT-N10', bytes, { sceneId: scene.id, bodyBlockId: scene.data.body[0].id, edgeId: edge.id, originalCondition: edge.data.condition, hostile });
  await seed(page, bytes);

  // when/then: edit the literal text, then display the same saved text in trial.
  await openEntity(page, 'scene', scene.name);
  await editBody(page, edited);
  // Full replacement has an actual new paragraph identity. Keep that saved
  // identity across all displays and cold rereads; import identity is separate.
  const editedSceneData = JSON.parse(await (await dataInput(page)).inputValue());
  expect(editedSceneData.body).toHaveLength(1);
  const editedBodyId = editedSceneData.body[0].id;
  expect(editedBodyId).toMatch(/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/);
  expect(editedBodyId).not.toBe(scene.data.body[0].id);
  expect(editedSceneData).toEqual({ ...scene.data, body: [{ ...scene.data.body[0], id: editedBodyId, text: edited }] });
  await page.locator('.detail-panel').getByRole('tab', { name: '確認表示', exact: true }).click();
  await expect(page.locator('.detail-panel .rich-text')).toContainText(edited);
  expect(await executableDom(page, '.detail-panel .rich-text')).toEqual({ scripts: 0, handlers: [], unsafeUrls: [] });
  await navigate(page, /^構成/);
  await page.getByRole('tab', { name: '試読・検査', exact: true }).click();
  await page.getByLabel('試読の開始点', { exact: true }).selectOption(entry.id);
  await page.getByRole('button', { name: '試読を始める', exact: true }).click();
  await expect(page.locator('.reader-sheet')).toContainText(edited);
  expect(await executableDom(page, '.reader-sheet')).toEqual({ scripts: 0, handlers: [], unsafeUrls: [] });
  await page.getByRole('button', { name: '安全な条件で進む', exact: true }).click();
  await expect(page.locator('.reader-trial-heading')).toContainText('意図した終端');

  // Create the public text through the ordinary range/copy UI, not a renderer call.
  await work(page, '目的別出力');
  await page.getByRole('button', { name: '公開範囲を作成', exact: true }).click();
  const dialog = page.getByRole('dialog');
  await dialog.getByLabel('公開用の作品名', { exact: true }).fill('AT-N10 公開資料');
  await dialog.getByLabel('追加する対象', { exact: true }).selectOption(scene.id);
  await dialog.getByLabel('選んだ対象の本文・表記を公開文へコピーする', { exact: true }).check();
  await dialog.getByRole('button', { name: '範囲を作成して内容を確認', exact: true }).click();
  await expect(dialog).toBeHidden();
  await expect(page.locator('#entity-name')).toHaveValue('AT-N10 公開資料 · 公開範囲');
  const confirmedProfileData = JSON.parse(await (await dataInput(page)).inputValue());
  expect(confirmedProfileData.includedIds).toEqual([scene.id]);
  expect(confirmedProfileData.includeAuthorNotes).toBe(false);
  expect(confirmedProfileData.publicTexts[scene.id].body.map((block: { text: string }) => block.text).join('\n')).toBe(edited);
  await page.getByLabel('情報の状態', { exact: true }).selectOption('confirmed');
  await page.locator('.editor-footer').getByRole('button', { name: /^(保存する|保存を再試行)$/ }).click();
  await expect(page.locator('.editor-save-state')).toContainText('端末内保存済み');
  await expect(page.getByLabel('情報の状態', { exact: true })).toHaveValue('confirmed');
  await work(page, '目的別出力');
  await page.getByLabel('出力目的', { exact: true }).selectOption('reader');
  await page.getByLabel('本文の出力形式', { exact: true }).selectOption('html');
  await page.getByRole('button', { name: '内容を検査・プレビュー', exact: true }).click();
  const artifact = page.locator('.export-artifact').filter({ has: page.getByRole('heading', { name: /\.html$/ }) });
  await expect(artifact).toBeVisible();
  await expect(artifact.locator('pre')).toContainText('&lt;script&gt;');
  const pending = page.waitForEvent('download');
  await artifact.getByRole('button', { name: 'この内容を保存', exact: true }).click();
  const htmlBytes = new Uint8Array(await readFile((await (await pending).path())!));
  await info.attach('AT-N10-public.html', { body: Buffer.from(htmlBytes), contentType: 'text/html' });
  const publicContext = await browser.newContext();
  try {
    const publicPage = await publicContext.newPage();
    // Open the actual downloaded document unchanged in an isolated origin.
    await publicPage.goto(`data:text/html;base64,${Buffer.from(htmlBytes).toString('base64')}`);
    await expect(publicPage.locator('body')).toContainText(edited);
    expect(await executableDom(publicPage, 'body')).toEqual({ scripts: 0, handlers: [], unsafeUrls: [] });
    expect(await publicPage.evaluate(() => Object.keys(globalThis).filter(key => /^__ap04.*Executed$/.test(key)))).toEqual([]);
  } finally { await publicContext.close(); }

  // negative_or_edge: a .png filename and declared image/png do not bless HTML.
  await work(page, '作品の設定');
  const beforeFile = await authorFingerprint(page);
  await page.getByLabel('素材ファイルを選ぶ', { exact: true }).setInputFiles({
    name: 'looks-like-image.png', mimeType: 'image/png', buffer: Buffer.from(`<html>${hostile}</html>`),
  });
  await expect(page.locator('.project-info').getByRole('alert')).toContainText('安全な表示の対象外');
  expect(await authorFingerprint(page)).toBe(beforeFile);

  // Arbitrary code is entered only through the actual JSON editor and rejected.
  await openEntity(page, 'flow_edge', edge.name);
  const raw = await dataInput(page), original = JSON.parse(await raw.inputValue());
  const beforeCondition = await authorFingerprint(page);
  const invalid = { ...original, condition: { op: 'javascript', source: 'globalThis.__ap04ConditionExecuted = true' } };
  await raw.fill(JSON.stringify(invalid, null, 2));
  await expect(page.locator('.detail-panel')).toContainText('未知の条件・式op');
  await expect(page.locator('.editor-footer').getByRole('button', { name: /保存する|保存を再試行/ })).toBeDisabled();
  await expect(raw).toHaveValue(JSON.stringify(invalid, null, 2));
  expect(await authorFingerprint(page)).toBe(beforeCondition);
  await raw.fill(JSON.stringify(original, null, 2));
  await page.locator('.editor-footer').getByRole('button', { name: /保存する|保存を再試行/ }).click();
  await expect(page.locator('.editor-save-state')).toContainText('端末内保存済み');
  expect(await page.evaluate(() => Object.keys(globalThis).filter(key => /^__ap04.*Executed$/.test(key)))).toEqual([]);
  await page.reload();
  const cold = await backup(page), coldScene = cold.project.entities.find(entity => entity.id === scene.id);
  expect(coldScene?.kind).toBe('scene');
  if (!coldScene || coldScene.kind !== 'scene') throw new Error('保存後の場面がありません');
  expect(coldScene.data).toEqual(editedSceneData);
  const editOperation = cold.project.history.find(command => command.before.entities.some(entity => entity.id === scene.id && entity.kind === 'scene' && entity.data.body[0]?.id === scene.data.body[0].id)
    && command.after.entities.some(entity => entity.id === scene.id && entity.kind === 'scene' && entity.data.body[0]?.id === editedBodyId && entity.data.body[0]?.text === edited));
  expect(editOperation).toBeDefined();
  const confirmedProfiles = cold.project.entities.filter(entity => entity.kind === 'projection_profile' && entity.name === 'AT-N10 公開資料 · 公開範囲');
  expect(confirmedProfiles).toHaveLength(1); expect(confirmedProfiles[0].status).toBe('confirmed'); expect(confirmedProfiles[0].data).toEqual(confirmedProfileData);
  expect(cold.project.entities.find(entity => entity.id === edge.id)?.data).toEqual(original);
  expect(cold.project.entities.some(entity => entity.kind === 'attachment')).toBe(false);
  await attachObservation(info, 'AT-N10-observation', { publicHtmlSha256: sha256(htmlBytes), publicHtmlBytes: htmlBytes.length, coldRevision: cold.project.revision, coldArchiveSha256: sha256(cold.bytes), originalBodyBlockId: scene.data.body[0].id, bodyBlockId: coldScene.data.body[0].id, editOperationId: editOperation?.operationId, confirmedProfile: confirmedProfiles[0], invalidConditionRetainedAndRejected: true, falseImageRejected: true });
});

