  await origin.getByRole('button', { name: '閉じる', exact: true }).click();
  // Replay each original record, then explicitly choose the registered reset.
  for (const trace of traces) {
    await page.locator('.saved-traces').getByRole('button', { name: `${trace.name} 再実行して状態を比較`, exact: true }).click();
    await page.getByRole('button', { name: keepDifference.data.label!, exact: true }).click();
    await expect(page.locator('.runtime-variable').filter({ hasText: affinity.name })).toContainText(trace.id === firstTrace.id ? '2' : '0');
    await expect(page.locator('.reader-state-counts').locator('dd').first()).toHaveText(trace.id === firstTrace.id ? '1個' : '0個');
    await page.locator('.saved-traces').getByRole('button', { name: `${trace.name} 再実行して状態を比較`, exact: true }).click();
    await expect(page.locator('.reader-sheet h2')).toHaveText(scene.name);
    await page.getByRole('button', { name: clearDifference.data.label!, exact: true }).click();
    await expect(page.locator('.runtime-variable').filter({ hasText: affinity.name })).toContainText('0');
    await expect(page.locator('.reader-trial-heading')).toContainText('意図した終端');
