test('AT-F18 終端・選択肢ゼロ・無制限反復・外部条件の同じgraphを原上限で探索し、区分と根拠経路を開く', async ({ page }, info) => {
  test.setTimeout(90_000);
  const p = createProject('AT-F18 原上限と結果区分');
  const counter = createEntity(p.projectId, 'variable', '値が増え続ける反復数', { key: 'unbounded_count', valueType: 'integer', scope: 'across_runs', initial: { type: 'integer', value: 0 }, allowed: {} });
  const increment = createEntity(p.projectId, 'effect', '反復数を一つ増やす', { operation: 'add', targetId: counter.id, value: { type: 'integer', value: 1 } });
  const external = createEntity(p.projectId, 'external_contract', '実行側が決める条件', { key: 'external_ready', owner: 'game', outputType: 'boolean', missingPolicy: 'unknown' });
  const entry = createEntity(p.projectId, 'flow_node', '結果区分の入口', { nodeType: 'entry' });
  const ending = createEntity(p.projectId, 'flow_node', '到達できる意図した終端', { nodeType: 'terminal', terminalReason: '作者が意図した終了' });
  const empty = createEntity(p.projectId, 'flow_node', '選択肢がゼロの分岐', { nodeType: 'choice' });
  const sameLoop = createEntity(p.projectId, 'flow_node', '同じ状態の無制限ループ', { nodeType: 'automatic', executionPolicy: 'first_match' });
  const countingLoop = createEntity(p.projectId, 'flow_node', '上限を調べる増加ループ', { nodeType: 'automatic', executionPolicy: 'first_match' });
  const externalNode = createEntity(p.projectId, 'flow_node', '外部条件の不足を確認する分岐', { nodeType: 'automatic', executionPolicy: 'first_match', gate: { op: 'external', contractId: external.id } });
  const targets = [ending, empty, sameLoop, externalNode, countingLoop];
  const branches = targets.map(target => createEntity(p.projectId, 'flow_edge', `入口から${target.name}`, { fromId: entry.id, toId: target.id, label: `入口から${target.name}` }));
  const repeat = createEntity(p.projectId, 'flow_edge', '同状態を反復する線', { fromId: sameLoop.id, toId: sameLoop.id, edgeType: 'automatic' });
  const countAgain = createEntity(p.projectId, 'flow_edge', '増加しながら反復する線', { fromId: countingLoop.id, toId: countingLoop.id, edgeType: 'automatic', effectIds: [increment.id] });
  const externalExit = createEntity(p.projectId, 'flow_edge', '外部条件確定後に終了', { fromId: externalNode.id, toId: ending.id, edgeType: 'automatic' });
  const nodes = [entry, ...targets], edges = [...branches, repeat, countAgain, externalExit];
  const graph = createEntity(p.projectId, 'flow_graph', '全結果を含む小さなgraph', { nodeIds: nodes.map(node => node.id), edgeIds: edges.map(edge => edge.id), entryIds: [entry.id], exitIds: [ending.id] });
  p.entities.push(counter, increment, external, ...nodes, ...edges, graph);
  p.entities.forEach(entity => { entity.status = 'confirmed'; });
  const bytes = await exportScenario(p), limits = { maxStates: 100000, maxTransitions: 10000, maxMs: 30000 };
  await attachGiven(info, 'AT-F18', bytes, { graphId: graph.id, nodeIds: nodes.map(node => node.id), terminalId: ending.id, noChoicesId: empty.id, sameStateLoopId: sameLoop.id, increasingLoopId: countingLoop.id, externalNodeId: externalNode.id, externalContractId: external.id, unchangedProductionLimits: limits });
  await seed(page, bytes);
  await reader(page);
  await page.getByLabel('試読の開始点', { exact: true }).selectOption(entry.id);
  const before = await authorFingerprint(page);
  await page.getByRole('button', { name: '到達性と行き止まりを検査', exact: true }).click();
  await expect(page.locator('.analysis-result-heading')).toContainText('探索打切り', { timeout: 35_000 });
  const download = page.waitForEvent('download');
  await page.getByRole('button', { name: '検査結果を保存', exact: true }).click();
  const analysis: AnalysisResult = JSON.parse(await readFile((await (await download).path())!, 'utf8'));
  expect(analysis.contentVersionId).toBe(p.projectId);
  expect(analysis.contentRevision).toBe(p.revision);
  expect(analysis.limits).toEqual(limits);
  expect(analysis.truncated).toBe(true);
  expect(analysis.status).toBe('unknown');
  expect(analysis.checkedStates).toBeGreaterThan(0);
  expect(analysis.checkedStates).toBeLessThanOrEqual(limits.maxStates);
  expect(analysis.findings.some(finding => finding.code === 'REFERENCE_INVALID')).toBe(false);
  const terminal = analysis.findings.find(finding => finding.code === 'TERMINAL' && finding.targetId === ending.id);
  const deadEnd = analysis.findings.find(finding => finding.targetId === empty.id && finding.status === 'candidate');
  const loop = analysis.findings.find(finding => finding.code === 'UNBOUNDED_LOOP' && finding.targetId === sameLoop.id);
  const unresolved = analysis.findings.find(finding => finding.code === 'CONDITION_UNKNOWN' && finding.targetId === externalNode.id);
  const cutoff = analysis.findings.find(finding => finding.code === 'ANALYSIS_LIMIT');
  expect(terminal).toMatchObject({ status: 'intentional', path: [entry.id, ending.id], edgePath: [[branches[0].id]] });
  expect(deadEnd).toMatchObject({ status: 'candidate', path: [entry.id, empty.id], edgePath: [[branches[1].id]] });
  expect(deadEnd?.message).toMatch(/進行|選択肢/);
  expect(loop?.status).toBe('unknown');
  expect(loop?.path[0]).toBe(entry.id);
  expect(loop?.path.at(-1)).toBe(sameLoop.id);
  expect(loop?.edgePath?.flat()).toContain(repeat.id);
  expect(unresolved).toMatchObject({ status: 'unknown', path: [entry.id, externalNode.id], edgePath: [[branches[3].id]] });
  expect(cutoff?.status).toBe('unknown');
  expect(cutoff?.message).toMatch(/上限|未確認/);
  await expect(page.locator('.analysis-section')).toContainText('外部値を補いません');
  await expect(page.locator('.analysis-section')).toContainText('意図した終端');
  await expect(page.locator('.analysis-section')).toContainText('確認候補');
  await expect(page.locator('.analysis-section')).toContainText('不明・探索未完了');
  const deadEndCard = page.locator('.analysis-section .analysis-finding').filter({ hasText: deadEnd!.message });
  await expect(deadEndCard.locator('.finding-path')).toContainText(`${entry.name} → ${empty.name}`);
  await deadEndCard.getByRole('button', { name: '対象を開く', exact: true }).click();
  await expect(page.locator('#entity-name')).toHaveValue(empty.name);
  await page.getByRole('button', { name: '詳細を閉じる', exact: true }).click();
  await reader(page);
  const loopCard = page.locator('.analysis-section .analysis-finding').filter({ hasText: loop!.message });
  await expect(loopCard.locator('.finding-path')).toContainText(sameLoop.name);
  await loopCard.getByRole('button', { name: '対象を開く', exact: true }).click();
  await expect(page.locator('#entity-name')).toHaveValue(sameLoop.name);
  await page.getByRole('button', { name: '詳細を閉じる', exact: true }).click();
  await reader(page);
  await expect(page.locator('.analysis-result-heading')).toContainText('探索打切り');
  expect(await authorFingerprint(page)).toBe(before);
  await attachObservation(info, 'AT-F18-observation', { analysis, finiteBoundsChanged: false, automaticExternalValueSupplied: false, cutoffProvesUnreachable: false, authorRecordsUnchanged: true });
});

