test('AT-F20 初回再訪と抽選3候補を固定 seed で戻り・再生し、run所持金とacross_runs記憶の周回・全resetと候補ゼロを比較する', async ({ page }, info) => {
  test.setTimeout(90_000);
  const p = createProject('AT-F20 初回再訪と抽選');
  const money = createEntity(p.projectId, 'variable', 'run 所持金', { key: 'money', valueType: 'integer', scope: 'run', initial: { type: 'integer', value: 0 }, allowed: { min: 0, max: 100 } });
