  const firstScene = createEntity(p.projectId, 'scene', '初回の反応', { body: textToRichText('初めまして。重要情報：鍵は赤い扉に使う。') });
  const againScene = createEntity(p.projectId, 'scene', '再訪の反応', { body: textToRichText('また会いましたね。重要情報：鍵は赤い扉に使う。') });
  const reaction = createEntity(p.projectId, 'flow_node', '初回再訪を選ぶ入口', { nodeType: 'entry', executionPolicy: 'first_match' });
  const first = createEntity(p.projectId, 'flow_node', '初回の提示', { nodeType: 'automatic', executionPolicy: 'first_match', sceneId: firstScene.id });
  const again = createEntity(p.projectId, 'flow_node', '再訪の提示', { nodeType: 'automatic', executionPolicy: 'first_match', sceneId: againScene.id });
  const draw = createEntity(p.projectId, 'flow_node', '3候補の抽選', { nodeType: 'choice', executionPolicy: 'manual_choice' });
  const noCandidates = createEntity(p.projectId, 'flow_node', '候補ゼロの停止先', { nodeType: 'terminal', terminalReason: '候補がなく抽選を止めた' });
  draw.data.fallbackId = noCandidates.id;
  const results = [1, 2, 3].map(index => createEntity(p.projectId, 'flow_node', `抽選結果${index}`, { nodeType: 'choice' }));
  const reward = createEntity(p.projectId, 'effect', '所持金を9増やす', { operation: 'add', targetId: money.id, value: { type: 'integer', value: 9 } });
  const remember = createEntity(p.projectId, 'effect', '重要情報を記憶する', { operation: 'set', targetId: memory.id, value: { type: 'boolean', value: true } });
  const firstEdge = createEntity(p.projectId, 'flow_edge', '初回反応へ', { fromId: reaction.id, toId: first.id, edgeType: 'automatic', priority: 0, condition: { op: 'not', child: { op: 'visited', entityId: first.id, count: 1 } } });
  const againEdge = createEntity(p.projectId, 'flow_edge', '再訪反応へ', { fromId: reaction.id, toId: again.id, edgeType: 'automatic', priority: 1, condition: { op: 'visited', entityId: first.id, count: 1 } });
  const toDraw = [first, again].map(node => createEntity(p.projectId, 'flow_edge', `${node.name}から抽選へ`, { fromId: node.id, toId: draw.id, edgeType: 'automatic', priority: 0 }));
  const candidates = results.map((result, index) => createEntity(p.projectId, 'flow_edge', `抽選候補${index + 1}`, { fromId: draw.id, toId: result.id, label: `抽選候補${index + 1}`, effectIds: [reward.id, remember.id], condition: { op: 'constant', value: true } }));
  const returns = results.map(result => createEntity(p.projectId, 'flow_edge', `${result.name}から再訪へ`, { fromId: result.id, toId: reaction.id, label: 'もう一度反応を見る' }));
