  await attachGiven(info, 'AT-F20', bytes, { firstSceneId: firstScene.id, againSceneId: againScene.id, drawNodeId: draw.id, candidateIds: candidates.map(candidate => candidate.id), moneyId: money.id, moneyScope: money.data.scope, memoryId: memory.id, memoryScope: memory.data.scope, seed: drawSeed, noCandidatesFallbackId: noCandidates.id });
