  await expect(page.locator('.runtime-variable').filter({ hasText: memory.name })).toContainText('true');
  await page.getByRole('button', { name: 'すべて初期化', exact: true }).click();
  await expect(page.locator('.runtime-variable').filter({ hasText: money.name })).toContainText('0');
